    &self,
    peer_id: PeerId,
    inbound_request_id: InboundRequestId,
    request: DataColumnsByRangeRequest<P>,
) -> Result<()> {
    debug!(
        "received DataColumnsByRange request (peer_id: {peer_id}, \
        inbound_request_id: {inbound_request_id:?}, request: {request:?})",
    );

    let start_epoch = misc::compute_epoch_at_slot::<P>(request.start_slot);

    if start_epoch < self.controller.min_checked_data_column_availability_epoch() {
        debug!(
            "received invalid request requesting data columns before availability period: \
            (peer_id: {peer_id}, inbound_request_id: {inbound_request_id:?}, \
            request: {request:?})",
        );

        ServiceInboundMessage::SendErrorResponse(
            peer_id,
            inbound_request_id,
            RpcErrorResponse::InvalidRequest,
            "requested data columns before data availability period",
        )
        .send(&self.network_to_service_tx);

        return Ok(());
    }

    let DataColumnsByRangeRequest {
        start_slot,
        count,
        columns,
    } = request;

    let difference = count.min(MAX_FOR_DOS_PREVENTION);

    let end_slot = start_slot
        .checked_add(difference)
        .ok_or(Error::EndSlotOverflow {
            start_slot,
            difference,
        })?;

    let controller = self.controller.clone_arc();
    let network_to_service_tx = self.network_to_service_tx.clone();
    let max_request_data_column_sidecars: usize = self
        .controller
        .chain_config()
        .max_request_data_column_sidecars
        .try_into()?;

    self.dedicated_executor
        .spawn(async move {
            // > Clients MAY limit the number of data column sidecars in the response.
            let mut data_column_sidecars = controller.data_column_sidecars_by_range(
                start_slot..end_slot,
                &columns,
                max_request_data_column_sidecars,
            )?;

            // > The following data column sidecars, where they exist, MUST be sent in (slot, column_index) order.
            data_column_sidecars.sort_by_key(|sidecar| (sidecar.slot(), sidecar.index));

            for data_column_sidecar in data_column_sidecars {
                let data_column_identifier: DataColumnIdentifier =
                    data_column_sidecar.as_ref().into();

                debug!(
                    "sending DataColumnsSidecarsByRange response chunk \
                    (inbound_request_id: {inbound_request_id:?}, peer_id: {peer_id}, \
                    slot: {}, id: {data_column_identifier:?})",
                    data_column_sidecar.slot(),
                );

                ServiceInboundMessage::SendResponse(
                    peer_id,
                    inbound_request_id,
                    Box::new(Response::DataColumnsByRange(Some(data_column_sidecar))),
                )
                .send(&network_to_service_tx);
            }

            debug!("terminating DataColumnsByRange response stream");

            ServiceInboundMessage::SendResponse(
                peer_id,
                inbound_request_id,
                Box::new(Response::DataColumnsByRange(None)),
            )
            .send(&network_to_service_tx);

            Ok::<_, anyhow::Error>(())
        })
        .detach();

    Ok(())
}

pub fn data_column_sidecars_by_range(
    &self,
    range: Range<Slot>,
    columns: &[ColumnIndex],
    max_request_data_column_sidecars: usize,
) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
    let canonical_chain_blocks = self.blocks_by_range(range)?;

    let data_column_ids = canonical_chain_blocks
        .iter()
        .filter_map(|BlockWithRoot { block, root }| {
            block.message().body().post_fulu().map(|_| {
                columns.iter().copied().map(|index| DataColumnIdentifier {
                    index,
                    block_root: *root,
                })
            })
        })
        .flatten()
        .take(max_request_data_column_sidecars);

    self.data_column_sidecars_by_ids(data_column_ids)
}

pub fn preprocessed_state_at_current_slot(&self) -> Result<Arc<BeaconState<P>>> {
    let store = self.store_snapshot();
    let head = store.head();

    self.state_cache()
        .state_at_slot(self.pubkey_cache(), &store, head.block_root, store.slot())
}

pub fn preprocessed_state_at_next_slot(&self) -> Result<Arc<BeaconState<P>>> {
    let store = self.store_snapshot();
    let head = store.head();

    self.state_cache().state_at_slot(
        self.pubkey_cache(),
        &store,
        head.block_root,
        store.slot() + 1,
    )
}

// The `block_root` and `state` parameters are needed
// to avoid a race condition in `Validator::slot_head`.
pub fn preprocessed_state_post_block(
    &self,
    block_root: H256,
    slot: Slot,
) -> Result<Arc<BeaconState<P>>> {
    self.preprocessed_state_post_block_with_cached_state(block_root, slot, || {
        self.state_cache().try_state_at_slot(
            self.pubkey_cache(),
            &self.store_snapshot(),
            block_root,
            slot,
        )
    })
}

// Modified `preprocessed_state_post_block` method to be used for block production.
pub fn preprocessed_state_for_block_production(
    &self,
    block_root: H256,
    slot: Slot,
) -> Result<Arc<BeaconState<P>>> {
    self.preprocessed_state_post_block_with_cached_state(block_root, slot, || {
        self.state_cache().try_state_at_slot_for_block_sync(
            self.pubkey_cache(),
            &self.store_snapshot(),
            block_root,
            slot,
        )
    })
}

